examples.template:
let tabs = TabView(selection: $tab) {
    NavigationStack {
        Color.clear
            .monarchCanvas()
            .navigationTitle({{nav.0.label}})
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
    }
    .tabItem { Label({{nav.0.label}}, systemImage: "house") }
    .tag({{nav.0.key}})
    NavigationStack {
        List {
            Section {
                    Text({{conversations.0}})
                    Text({{conversations.1}})
                    Text({{conversations.2}})
                    Text({{conversations.3}})
                    Text({{conversations.4}})
                    Text({{conversations.5}})
                    Text({{conversations.6}})
                    Text({{conversations.7}})
                    Text({{conversations.8}})
                    Text({{conversations.9}})
                    Text({{conversations.10}})
                    Text({{conversations.11}})
            } header: {
                Text({{header.description}})
            }
        }
        .listStyle(.plain)
        .monarchCanvas()
        .navigationTitle({{header.title}})
        #if os(iOS)
        .navigationBarTitleDisplayMode(.inline)
        #endif
        #if os(iOS)
        .toolbar {
            // The product name and the signed-in person, as the identity bar of the web shell.
            ToolbarItem(placement: .topBarLeading) {
                Text({{product}}).monarchTextStyle(.bodyStrong).fixedSize()
            }
            .monarchFlat()
            ToolbarItem(placement: .topBarTrailing) {
                MonarchAvatar(url: nil, name: {{account.name}}, size: .sm, isDecorative: true)
            }
            .monarchFlat()
        }
        #endif
    }
    .tabItem { Label({{nav.1.label}}, systemImage: "tray") }
    .badge({{nav.1.badge}})
    .tag({{nav.1.key}})
    NavigationStack {
        Color.clear
            .monarchCanvas()
            .navigationTitle({{nav.2.label}})
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
    }
    .tabItem { Label({{nav.2.label}}, systemImage: "calendar") }
    .tag({{nav.2.key}})
}
Group {
    if #available(iOS 18.0, macOS 15.0, *) {
        tabs.tabViewStyle(.sidebarAdaptable)
    } else {
        tabs
    }
}
.frame(minHeight: theme.spacing.space24 * 3)

